        END IF;
      END IF;
    ELSIF gvalid /= '0' THEN 
      IF parIndTmp /= '0' THEN 
        FOR t_0 IN 0 TO 44 LOOP
          iterationController45_pwrData_next(t_0) <= gamma_signed(t_0);
          iterationController45_pwrEnb_next(t_0) <= gwrenb(t_0);
          iterationController45_iwrEnb_next(t_0) <= '0';
        END LOOP;
      ELSE 
        iterationController45_iwrData_next <= gamma_signed;
        iterationController45_iwrEnb_next <= (OTHERS => '1');
        iterationController45_pwrEnb_next <= (OTHERS => '0');
      END IF;
      iterationController45_iwrAddr_next <= to_unsigned(16#001#, 11);
      iterationController45_pwrAddr_next <= to_unsigned(16#001#, 11);
    ELSE 
      iterationController45_pwrData_next <= (OTHERS => to_signed(16#000#, 11));
      iterationController45_pwrEnb_next <= (OTHERS => '0');
      iterationController45_iwrData_next <= (OTHERS => to_signed(16#000#, 11));
