      iterationController45_pwrAddr_next <= to_unsigned(16#001#, 11);
    END IF;
    trigger := sResetReg OR layerDone1;
    IF (rdEnb_temp AND dataSel_temp) = '1' THEN 
      sub_temp_0 := degreeValTmp - to_unsigned(16#02#, 5);
      IF ivalidCount_temp = sub_temp_0 THEN 
        IF pvalidCount_temp = to_unsigned(16#2#, 2) THEN 
          rdEnb_temp := '0';
          ivalidCount_temp := to_unsigned(16#00#, 5);
          pvalidCount_temp := to_unsigned(16#0#, 2);
