      END IF;
    ELSE 
      iterationController45_parityRead_next <= '0';
      pvalidCount_temp := to_unsigned(16#0#, 2);
      ivalidCount_temp := to_unsigned(16#00#, 5);
    END IF;
    IF ((trigger AND ( NOT iterDone_temp)) AND dataSel_temp) = '1' THEN 
      rdEnb_temp := '1';
    ELSIF iterDone_temp = '1' THEN 
      rdEnb_temp := '0';
    END IF;
    iterationController45_rdValid_next <= rdEnb_temp;
    IF reset_1 /= '0' THEN 
      finalEnb_temp := '0';
    ELSIF iterDone_temp = '1' THEN 
      finalEnb_temp := '1';
    END IF;
    IF reset_1 /= '0' THEN 
      iterationController45_rdCount_next <= to_unsigned(16#0000#, 16);
      fcount_temp := to_unsigned(16#0#, 4);
      faCount_temp := to_unsigned(16#000#, 11);
