  BEGIN
    IF intReset /= '0' THEN 
      prdDataTmp <= (OTHERS => to_signed(16#000#, 11));
    ELSIF parityVNReading_rdValid = '1' THEN 
      IF (layerIdx_1 = to_unsigned(16#001#, 11)) AND (parityVNReading_count = to_unsigned(16#1#, 3)) THEN 
