        prdDataTmp(1 TO 44) <= parityVNReading_rdData(0 TO 43);
      ELSIF (layerIdx_1 = to_unsigned(16#001#, 11)) AND (parityVNReading_count = to_unsigned(16#2#, 3)) THEN 
        prdDataTmp(0) <= to_signed(16#3FF#, 11);
        prdDataTmp(1 TO 44) <= parityVNReading_rdData(1 TO 44);
      ELSE 
        prdDataTmp <= parityVNReading_rdData;
      END IF;
    ELSE 
      prdDataTmp <= (OTHERS => to_signed(16#000#, 11));
    END IF;
    parityVNReading_rdData_next <= prdData;
    IF intReset /= '0' THEN 
      parityVNReading_count_next <= to_unsigned(16#0#, 3);
    ELSIF parityInd = '1' THEN 
      IF parityVNReading_count = to_unsigned(16#2#, 3) THEN 
        parityVNReading_count_next <= to_unsigned(16#0#, 3);
      ELSE 
        parityVNReading_count_next <= parityVNReading_count + to_unsigned(16#1#, 3);
      END IF;
    ELSE 
      parityVNReading_count_next <= to_unsigned(16#0#, 3);
